import{_ as e,c as o,o as n,ae as s}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"ACF/Metabox/JetEngine/Toolset/Pods Integration with Ninja Tables","description":"ACF/Metabox/JetEngine/Toolset/Pods Integration with Ninja Tables","frontmatter":{"title":"ACF/Metabox/JetEngine/Toolset/Pods Integration with Ninja Tables","description":"ACF/Metabox/JetEngine/Toolset/Pods Integration with Ninja Tables"},"headers":[],"relativePath":"guide/wordpress-integration/acf-metabox-jetengine-toolset-pods-integration-with-ninja-tables.md","filePath":"guide/wordpress-integration/acf-metabox-jetengine-toolset-pods-integration-with-ninja-tables.md"}'),a={name:"guide/wordpress-integration/acf-metabox-jetengine-toolset-pods-integration-with-ninja-tables.md"};function i(l,t,r,g,d,p){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="acf-metabox-jetengine-toolset-pods-integration-with-ninja-tables" tabindex="-1">ACF/Metabox/JetEngine/Toolset/Pods Integration with Ninja Tables <a class="header-anchor" href="#acf-metabox-jetengine-toolset-pods-integration-with-ninja-tables" aria-label="Permalink to &quot;ACF/Metabox/JetEngine/Toolset/Pods Integration with Ninja Tables&quot;">​</a></h1><p><strong>JetEngine</strong> is used for Custom post types and relations between these post types. Let’s have a look at how JetEngine Integration works in Ninja Tables.</p><ul><li>To build a Custom Post type, you must have the <strong>JetEngine</strong> Plugin installed first.</li><li>Then, you need to create a <strong>New</strong> <strong>Post</strong> **type, <strong>or you can also work on the</strong> **existing <strong>Post</strong> <strong>Type</strong>.</li><li>Go to the <strong>JetEngine dashboard →</strong> click on <strong>Post Types,</strong> and <strong>General</strong> <strong>Settings</strong> will appear. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-7-1.png" alt="Add New Post Type"></li><li>You must add some <strong>Custom</strong> <strong>Fields</strong> to the Custom Post Type.</li><li>Give your Post Type Name and Post Type Slug and enable** **the Edit Post type/meta box link. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-4-1.png" alt="General Settings"></li><li>Also, go to the <strong>Labels</strong> &amp; <strong>Advanced</strong> <strong>Settings</strong> &amp; give the fields name according to your needs.</li><li>Click on the <strong>New Meta Field</strong> button to add Meta Fields <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-9-1024x474.png" alt="New Meta Field"></li><li>There are available <strong>Field types</strong> where you can choose one according to your needs. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-2.png" alt="Field Type"></li><li>To get your <strong>Post Meta Key Name,</strong> you need to go back to <strong>JetEngine</strong> <strong>→</strong> <strong>Post</strong> <strong>Type</strong>.</li><li>Then, navigate to the <strong>Meta Fields</strong> &amp; here, the Name/ID of every Meta Field is Meta Key. For instance, &quot;name&quot; is the meta key of the Name Field as follows; the date is the Meta Key of the Date field.</li><li>Copy the <strong>Meta Key</strong> to use this in a further step.</li><li>Lastly, click on the **Add Post Type **button after your configuration is done.</li><li>Now, go to the <strong>Jet Engine CPT</strong> and go to the **Add New **button. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-6-1.png" alt="Jet Engine CPT"></li><li>Here, you will see the <strong>Meta Field</strong> has been added. Click on the <strong>Publish</strong> button when you are done. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-1-1.png" alt="meta field JetEngine"> Custom Post Type will work only with WP Posts &amp; WooCommerce Table!</li><li>Now, navigate to the <strong>Ninja Tables</strong> plugin and go to a** Post Table**. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-4-1024x560.png" alt="Post Table"></li><li>You must go to the Ninja Tables <strong>Add</strong> <strong>New</strong> <strong>Column</strong> <strong>button</strong> to add a new column when using a Custom Post field in a Custom Post Type.</li><li>Give your Column Name and other field names.</li><li>Choose Shortcode/Computed Value or HTML from the Field Type option in Dynamic Post Data Settings. After choosing the Shortcode/Computed value field type, some customized dynamic field values will be shown below.</li><li>In the Field Value option, for Post Meta, put your post meta key shortcode in the field. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-2-1.png" alt="Dynamic Post Data Settings"></li><li>Go back to the <strong>Dynamic Post Data Settings</strong>, put your <strong>Post Meta key,</strong> and click on the <strong>Add Column</strong> button.</li><li>Then, the custom columns will be added. It will be showing up on the table like this. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-JetEngine-E-8-1.png" alt="Preview"> By following the same steps, anyone can integrate JetEngine/ACF/Metabox/Toolset/Pods with Ninja Tables!</li></ul>',3)])])}const u=e(a,[["render",i]]);export{c as __pageData,u as default};
